    const title = node?.layout === 'grid' && node.diagram ? diagramTitle(node.diagram) : 'New diagram';
    const key = prompts.open({ operation, canvasId, documentId, nodeId, label: `${draft.name} / ${captured.subtreeLabel ?? title}`,
